import math
def rh(x): 
    return math.floor(x+0.5) if x>=0 else -math.floor(-x+0.5)
# python round-half-away-from-zero emulation of Rust f64::round
def rround(x):
    return math.copysign(math.floor(abs(x)+0.5), x) if abs(x - math.trunc(x)) != 0.5 else math.copysign(math.trunc(abs(x))+1, x)
cands=[]
import itertools
xs=[i/100 for i in range(1,100000)]
for x in xs:
    a=rround(x*0.9*10)/10
    b=rround(x*9)/10
    c=rround(x*0.9/0.1)/10*1
    d=rround(x*0.9*10)*0.1
    if len({a,b,d})>1:
        cands.append((x,a,b,d))
print(len(cands)); print(cands[:20])
"

