//! Electrical settings: `voltage`, `distribution_system`, `wire_type`.
//!
//! The file keeps them in `voltages`, `distribution_systems` and `wire_types`, each by name in
//! name order, and the library names each (`voltage`, `distribution-system`, `wire-type`) with its
//! GUID; a distribution system names its voltages by their GUIDs. A command takes an entry by its
//! name or its GUID.

use super::common::*;
use crate::json::{Map, Num, Value};
use crate::project::Project;
use crate::session::Session;

pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    match cid {
        "voltage" => voltage(s, p),
        "distribution_system" => distribution_system(s, p),
        "wire_type" => wire_type(s, p),
        _ => Err(format!("{}: not supported here", cid)),
    }
}

/// What `inspect` says of the electrical settings.
pub fn inspect_entries(s: &Session, out: &mut Vec<(String, Value)>) {
    let pr = &s.project;
    out.push(("voltages".into(), Value::Obj(section(pr, "voltages"))));
    out.push(("distribution_systems".into(), systems_shown(pr)));
    out.push(("wire_types".into(), Value::Obj(section(pr, "wire_types"))));
}

// ---------------------------------------------------------------- shared

/// An entry's name from its name or its GUID.
pub fn resolve(pr: &Project, kind: &str, name: &str) -> String {
    if let Some(g) = crate::model::normalize_guid(name) {
        if let Some(n) = name_of_guid(pr, kind, &g) {
            return n;
        }
    }
    name.to_string()
}

/// A text parameter as given (not trimmed); None when absent or null.
fn opt_raw_text(p: &Value, cmd: &str, key: &str) -> R<Option<String>> {
    crate::commands::params::opt_text(p, cmd, key)
}

/// A number of some unit: "`key` must be a number of volts, got …".
fn opt_number(p: &Value, cmd: &str, key: &str, unit: &str) -> R<Option<f64>> {
    match p.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(Value::Num(n)) => Ok(Some(n.as_f64())),
        Some(v) => Err(format!("{}: `{}` must be a number of {}, got {}", cmd, key, unit, v.to_compact())),
    }
}

/// A whole number 0 to 255 (serde's u8).
fn opt_u8(p: &Value, cmd: &str, key: &str) -> R<Option<u64>> {
    match p.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(Value::Num(Num::U(u))) if *u <= 255 => Ok(Some(*u)),
        Some(v) => Err(format!("{}: `{}` must be a whole number from 0 to 255, got {}", cmd, key, v.to_compact())),
    }
}

/// Puts an entry into a section in name order, under its new name when renamed.
fn put(pr: &mut Project, key: &str, old: &str, new: &str, v: Value) {
    let sec = pr.section_mut(key);
    if old != new {
        sec.remove(old);
    }
    sec.insert_sorted(new, v);
}

/// The library entry follows: renamed, or made for a new entry.
fn lib_follow(pr: &mut Project, kind: &str, old: &str, new: &str, existed: bool) {
    if existed {
        if old != new {
            lib_rename(pr, kind, old, new);
        }
    } else {
        lib_ensure(pr, kind, new);
    }
}

fn round1(x: f64) -> f64 {
    (x * 10.0).round() / 10.0
}

// ---------------------------------------------------------------- voltages

fn voltage(s: &mut Session, p: &Value) -> R<Value> {
    const CMD: &str = "voltage";
    check_keys(p, CMD, &["name", "nominal", "min", "max", "rename", "delete"])?;
    let pr = &mut s.project;
    let Some(name) = opt_name(p, CMD, "name")? else {
        return Ok(jobj! {"voltages" => Value::Obj(section(pr, "voltages"))});
    };
    let name = resolve(pr, "voltage", &name);
    let existing = pr.section("voltages").and_then(|m| m.get(&name)).cloned();
    if opt_bool(p, CMD, "delete")? == Some(true) {
        if existing.is_none() {
            return Err(format!("{}: there's no voltage `{}`", CMD, name));
        }
        if let Some(g) = pr.lib_guid("voltage", &name) {
            let systems = section(pr, "distribution_systems");
            let mut names: Vec<&String> = systems.keys().collect();
            names.sort();
            for dn in names {
                let ds = systems.get(dn).unwrap();
                if ["l_l", "l_n", "l_g"].iter().any(|k| ds.get(k).and_then(|x| x.as_str()) == Some(g.as_str())) {
                    return Err(format!(
                        "{}: voltage `{}` is one distribution system `{}` supplies: change or delete that first",
                        CMD, name, dn
                    ));
                }
            }
        }
        pr.section_mut("voltages").remove(&name);
        lib_remove(pr, "voltage", &name);
        super::mark_step();
        return Ok(jobj! {"deleted" => name});
    }
    let rename = opt_name(p, CMD, "rename")?;
    if rename.is_some() && existing.is_none() {
        return Err(format!("{}: there's no voltage `{}` to rename", CMD, name));
    }
    let nominal = opt_number(p, CMD, "nominal", "volts")?;
    if nominal.is_none() && existing.is_none() {
        return Err(format!("{}: `nominal` (volts) is required for a new voltage", CMD));
    }
    let min = opt_number(p, CMD, "min", "volts")?;
    let max = opt_number(p, CMD, "max", "volts")?;
    let target = rename.unwrap_or_else(|| name.clone());
    if target != name && pr.section("voltages").map(|m| m.contains(&target)).unwrap_or(false) {
        return Err(format!("{}: there's already a voltage `{}`", CMD, target));
    }
    let old = |k: &str| existing.as_ref().and_then(|e| e.get(k)).and_then(|x| x.as_f64());
    let nominal = nominal.or_else(|| old("nominal")).unwrap_or(0.0);
    let min = min.or_else(|| old("min")).unwrap_or_else(|| round1(nominal * 0.9));
    let max = max.or_else(|| old("max")).unwrap_or_else(|| round1(nominal * 1.1));
    let what = format!("{}: voltage `{}`", CMD, target);
    if !(nominal > 0.0 && nominal <= 100000.0) {
        return Err(format!("{}: `nominal` is volts above 0 and up to 100000, not {}", what, disp(nominal)));
    }
    if !(min > 0.0 && min <= nominal) {
        return Err(format!(
            "{}: `min` is volts above 0 and not above the nominal {} V, not {}",
            what,
            disp(nominal),
            disp(min)
        ));
    }
    if !(max >= nominal && max <= 100000.0) {
        return Err(format!(
            "{}: `max` is volts up to 100000 and not under the nominal {} V, not {}",
            what,
            disp(nominal),
            disp(max)
        ));
    }
    let v = jobj! {"nominal" => nominal, "min" => min, "max" => max};
    put(pr, "voltages", &name, &target, v.clone());
    lib_follow(pr, "voltage", &name, &target, existing.is_some());
    super::mark_step();
    Ok(jobj! {"name" => target, "voltage" => v})
}

// ---------------------------------------------------------------- distribution systems

const GROUNDS: &[&str] = &["TN-S", "TN-C", "TN-C-S", "TT", "IT"];

/// A distribution system as a reply shows it: its voltages by name.
fn system_shown(pr: &Project, ds: &Value) -> Value {
    let mut out = Map::new();
    if let Some(m) = ds.as_obj() {
        for (k, v) in &m.items {
            if matches!(k.as_str(), "l_l" | "l_n" | "l_g") {
                let g = v.as_str().unwrap_or("");
                let n = name_of_guid(pr, "voltage", g).unwrap_or_else(|| g.to_string());
                out.insert(k, Value::Str(n));
            } else {
                out.insert(k, v.clone());
            }
        }
    }
    Value::Obj(out)
}

fn systems_shown(pr: &Project) -> Value {
    let mut out = Map::new();
    for (k, v) in section(pr, "distribution_systems").items {
        out.insert(&k, system_shown(pr, &v));
    }
    Value::Obj(out)
}

fn distribution_system(s: &mut Session, p: &Value) -> R<Value> {
    const CMD: &str = "distribution_system";
    check_keys(p, CMD, &["name", "phases", "wires", "l_l", "l_n", "l_g", "ground", "rename", "delete"])?;
    let pr = &mut s.project;
    let Some(name) = opt_name(p, CMD, "name")? else {
        return Ok(jobj! {"distribution_systems" => systems_shown(pr)});
    };
    let name = resolve(pr, "distribution-system", &name);
    let existing = pr.section("distribution_systems").and_then(|m| m.get(&name)).cloned();
    if opt_bool(p, CMD, "delete")? == Some(true) {
        if existing.is_none() {
            return Err(format!("{}: there's no distribution system `{}`", CMD, name));
        }
        pr.section_mut("distribution_systems").remove(&name);
        lib_remove(pr, "distribution-system", &name);
        super::mark_step();
        return Ok(jobj! {"deleted" => name});
    }
    let rename = opt_name(p, CMD, "rename")?;
    if rename.is_some() && existing.is_none() {
        return Err(format!("{}: there's no distribution system `{}` to rename", CMD, name));
    }
    let phases = opt_u8(p, CMD, "phases")?;
    if phases.is_none() && existing.is_none() {
        return Err(format!("{}: `phases` (1, 2 or 3) is required for a new distribution system", CMD));
    }
    let wires = opt_u8(p, CMD, "wires")?;
    if wires.is_none() && existing.is_none() {
        return Err(format!(
            "{}: `wires` (the line conductors and the neutral) is required for a new distribution system",
            CMD
        ));
    }
    // each voltage: None, not given; Some(None), taken away; Some(Some(name))
    let mut volts: Vec<(&str, Option<Option<String>>)> = Vec::new();
    for k in ["l_l", "l_n", "l_g"] {
        let v = opt_raw_text(p, CMD, k)?.map(|t| {
            let t = t.trim().to_string();
            if t.is_empty() {
                None
            } else {
                Some(t)
            }
        });
        volts.push((k, v));
    }
    let ground = opt_raw_text(p, CMD, "ground")?.map(|t| {
        let t = t.trim().to_string();
        if t.is_empty() {
            None
        } else {
            Some(t)
        }
    });
    let target = rename.unwrap_or_else(|| name.clone());
    if target != name && pr.section("distribution_systems").map(|m| m.contains(&target)).unwrap_or(false) {
        return Err(format!("{}: there's already a distribution system `{}`", CMD, target));
    }
    let old = existing.clone().unwrap_or_else(Value::obj);
    let phases = phases.or_else(|| old.get("phases").and_then(|x| x.as_u64())).unwrap_or(0);
    let wires = wires.or_else(|| old.get("wires").and_then(|x| x.as_u64())).unwrap_or(0);
    // the voltages by name (a GUID given resolved), as they will be
    let mut named: Vec<(&str, Option<String>)> = Vec::new();
    for (k, v) in &volts {
        let n = match v {
            Some(x) => x.clone().map(|n| resolve(pr, "voltage", &n)),
            None => old
                .get(k)
                .and_then(|g| g.as_str())
                .map(|g| name_of_guid(pr, "voltage", g).unwrap_or_else(|| g.to_string())),
        };
        named.push((k, n));
    }
    let ground = match ground {
        Some(g) => g,
        None => old.get("ground").and_then(|g| g.as_str()).map(|g| g.to_string()),
    };
    let what = format!("{}: distribution system `{}`", CMD, target);
    if !(1..=3).contains(&phases) {
        return Err(format!("{}: `phases` is 1, 2 or 3, not {}", what, phases));
    }
    let lo = phases.max(2);
    let hi = phases + 1;
    if wires < lo || wires > hi {
        return Err(format!(
            "{}: `wires` counts the line conductors and the neutral, not the protective one: {} to {} for {} {}, not {}",
            what,
            lo,
            hi,
            phases,
            if phases == 1 { "phase" } else { "phases" },
            wires
        ));
    }
    if named.iter().all(|(_, n)| n.is_none()) {
        return Err(format!("{}: it supplies no voltage; give `l_l`, `l_n` or `l_g`", what));
    }
    if phases >= 2 && named[0].1.is_none() {
        return Err(format!("{}: `l_l`, the voltage between lines, is required for {} phases", what, phases));
    }
    let voltages = section(pr, "voltages");
    for (k, n) in &named {
        if let Some(n) = n {
            if !voltages.contains(n) {
                let mut have: Vec<&String> = voltages.keys().collect();
                have.sort();
                let have: Vec<&str> = have.iter().map(|s| s.as_str()).collect();
                return Err(format!(
                    "{}: `{}` names voltage `{}`, which the project doesn't have (there are: {})",
                    what,
                    k,
                    n,
                    have.join(", ")
                ));
            }
        }
    }
    if phases == 3 {
        if let (Some(ll), Some(ln)) = (&named[0].1, &named[1].1) {
            let vl = voltages.get(ll).and_then(|v| v.get("nominal")).and_then(|x| x.as_f64()).unwrap_or(0.0);
            let vn = voltages.get(ln).and_then(|v| v.get("nominal")).and_then(|x| x.as_f64()).unwrap_or(0.0);
            let s3 = 3f64.sqrt();
            if !((vl / vn) / s3 - 1.0).abs().le(&0.03) {
                return Err(format!(
                    "{}: with 3 phases `l_l` `{}` ({} V) should be about 1.73 times `l_n` `{}` ({} V)",
                    what,
                    ll,
                    disp(vl),
                    ln,
                    disp(vn)
                ));
            }
        }
    }
    if let Some(g) = &ground {
        if !GROUNDS.contains(&g.as_str()) {
            return Err(format!("{}: `ground` is the earthing, one of {}, not `{}`", what, GROUNDS.join(", "), g));
        }
    }
    let mut m = Map::new();
    m.insert("phases", Value::u(phases));
    m.insert("wires", Value::u(wires));
    for (k, n) in &named {
        if let Some(n) = n {
            let g = pr.lib_guid("voltage", n).unwrap_or_else(|| lib_ensure(pr, "voltage", n));
            m.insert(k, Value::Str(g));
        }
    }
    if let Some(g) = ground {
        m.insert("ground", Value::Str(g));
    }
    let v = Value::Obj(m);
    put(pr, "distribution_systems", &name, &target, v.clone());
    lib_follow(pr, "distribution-system", &name, &target, existing.is_some());
    super::mark_step();
    let shown = system_shown(pr, &v);
    Ok(jobj! {"distribution_system" => shown, "name" => target})
}

// ---------------------------------------------------------------- wire types

const MATERIALS: &[&str] = &["copper", "aluminium"];

struct Size {
    section: f64,
    ampacity: f64,
    label: Option<String>,
}

/// One row of `sizes`, as serde reads a `WireSize` {section, ampacity, label?}: from a map
/// (its keys in order, unknown ones refused) or from a sequence.
fn size_of(v: &Value) -> Result<Size, String> {
    let label_of = |x: &Value| -> Result<Option<String>, String> {
        match x {
            Value::Null => Ok(None),
            Value::Str(s) => Ok(Some(s.clone())),
            other => Err(invalid_type(other, "a string")),
        }
    };
    match v {
        Value::Obj(_) => {
            let sorted = v.clone().sorted();
            let m = sorted.as_obj().unwrap();
            let (mut section, mut ampacity, mut label) = (None, None, None);
            for (k, x) in &m.items {
                match k.as_str() {
                    "section" => section = Some(f64_of(x)?),
                    "ampacity" => ampacity = Some(f64_of(x)?),
                    "label" => label = Some(label_of(x)?),
                    other => {
                        return Err(format!(
                            "unknown field `{}`, expected one of `section`, `ampacity`, `label`",
                            other
                        ))
                    }
                }
            }
            let section = section.ok_or("missing field `section`")?;
            let ampacity = ampacity.ok_or("missing field `ampacity`")?;
            Ok(Size { section, ampacity, label: label.flatten() })
        }
        Value::Arr(a) => {
            let short = |n: usize| format!("invalid length {}, expected struct WireSize with 3 elements", n);
            let section = f64_of(a.first().ok_or_else(|| short(0))?)?;
            let ampacity = f64_of(a.get(1).ok_or_else(|| short(1))?)?;
            let label = match a.get(2) {
                Some(x) => label_of(x)?,
                None => None,
            };
            if a.len() > 3 {
                return Err(format!("invalid length {}, expected fewer elements in array", a.len()));
            }
            Ok(Size { section, ampacity, label })
        }
        other => Err(invalid_type(other, "struct WireSize")),
    }
}

fn sizes_of(v: &Value) -> Result<Vec<Size>, String> {
    match v {
        Value::Arr(a) => a.iter().map(size_of).collect(),
        other => Err(invalid_type(other, "a sequence")),
    }
}

fn size_value(s: &Size) -> Value {
    let mut m = Map::new();
    m.insert("section", Value::f(s.section));
    m.insert("ampacity", Value::f(s.ampacity));
    if let Some(l) = &s.label {
        m.insert("label", Value::Str(l.clone()));
    }
    Value::Obj(m)
}

fn wire_type(s: &mut Session, p: &Value) -> R<Value> {
    const CMD: &str = "wire_type";
    check_keys(p, CMD, &["name", "material", "temperature", "insulation", "note", "sizes", "rename", "delete"])?;
    let pr = &mut s.project;
    let Some(name) = opt_name(p, CMD, "name")? else {
        return Ok(jobj! {"wire_types" => Value::Obj(section(pr, "wire_types"))});
    };
    let name = resolve(pr, "wire-type", &name);
    let existing = pr.section("wire_types").and_then(|m| m.get(&name)).cloned();
    if opt_bool(p, CMD, "delete")? == Some(true) {
        if existing.is_none() {
            return Err(format!("{}: there's no wire type `{}`", CMD, name));
        }
        pr.section_mut("wire_types").remove(&name);
        lib_remove(pr, "wire-type", &name);
        super::mark_step();
        return Ok(jobj! {"deleted" => name});
    }
    let rename = opt_name(p, CMD, "rename")?;
    if rename.is_some() && existing.is_none() {
        return Err(format!("{}: there's no wire type `{}` to rename", CMD, name));
    }
    let new = existing.is_none();
    let material = opt_raw_text(p, CMD, "material")?;
    if material.is_none() && new {
        return Err(format!("{}: `material` (copper, aluminium) is required for a new wire type", CMD));
    }
    let temperature = opt_number(p, CMD, "temperature", "°C")?;
    if temperature.is_none() && new {
        return Err(format!("{}: `temperature` (°C) is required for a new wire type", CMD));
    }
    let insulation = opt_raw_text(p, CMD, "insulation")?;
    if insulation.is_none() && new {
        return Err(format!("{}: `insulation` is required for a new wire type", CMD));
    }
    let note = opt_raw_text(p, CMD, "note")?;
    let sizes = match p.get("sizes") {
        None | Some(Value::Null) => None,
        Some(v) => {
            let rows = sizes_of(v)
                .map_err(|e| format!("{}: `sizes` must be a list of {{section, ampacity, label?}}: {}", CMD, e))?;
            if rows.len() > 64 {
                return Err(format!("{}: `sizes` holds up to 64 rows", CMD));
            }
            Some(rows)
        }
    };
    if sizes.is_none() && new {
        return Err(format!("{}: `sizes` [{{section, ampacity}}, …] is required for a new wire type", CMD));
    }
    let target = rename.unwrap_or_else(|| name.clone());
    if target != name && pr.section("wire_types").map(|m| m.contains(&target)).unwrap_or(false) {
        return Err(format!("{}: there's already a wire type `{}`", CMD, target));
    }
    let old = existing.clone().unwrap_or_else(Value::obj);
    let text = |k: &str| old.get(k).and_then(|x| x.as_str()).map(|x| x.to_string());
    let material = material.or_else(|| text("material")).unwrap_or_default();
    let temperature = temperature.or_else(|| old.get("temperature").and_then(|x| x.as_f64())).unwrap_or(0.0);
    let insulation = insulation.or_else(|| text("insulation")).unwrap_or_default();
    let note = match note {
        Some(n) if n.is_empty() => None,
        Some(n) => Some(n),
        None => text("note"),
    };
    let sizes = match sizes {
        Some(s) => s,
        None => old
            .get("sizes")
            .and_then(|x| x.as_arr())
            .map(|a| a.iter().filter_map(|r| size_of(r).ok()).collect())
            .unwrap_or_default(),
    };
    let what = format!("{}: wire type `{}`", CMD, target);
    if !MATERIALS.contains(&material.as_str()) {
        return Err(format!("{}: `material` is one of {}, not `{}`", what, MATERIALS.join(", "), material));
    }
    if !(temperature > 0.0 && temperature <= 250.0) {
        return Err(format!("{}: `temperature` is °C above 0 and up to 250, not {}", what, disp(temperature)));
    }
    if insulation.trim().is_empty() {
        return Err(format!("{}: `insulation` is 1 to 256 characters", what));
    }
    if sizes.is_empty() {
        return Err(format!("{}: `sizes` holds 1 to 64 rows, not 0", what));
    }
    for (i, r) in sizes.iter().enumerate() {
        let row = i + 1;
        if !(r.section > 0.0 && r.section <= 10000.0) {
            return Err(format!(
                "{}: row {}: `section` is mm² above 0 and up to 10000, not {}",
                what,
                row,
                disp(r.section)
            ));
        }
        if !(r.ampacity > 0.0 && r.ampacity <= 100000.0) {
            return Err(format!(
                "{}: row {}: `ampacity` is amperes above 0 and up to 100000, not {}",
                what,
                row,
                disp(r.ampacity)
            ));
        }
        if i > 0 {
            let prev = &sizes[i - 1];
            if !(r.section > prev.section) {
                return Err(format!(
                    "{}: row {}: `section` {} mm² must be larger than the row before's {} mm²",
                    what,
                    row,
                    disp(r.section),
                    disp(prev.section)
                ));
            }
            if r.ampacity < prev.ampacity {
                return Err(format!(
                    "{}: row {}: `ampacity` {} A is less than the row before's {} A: a larger section carries at least as much",
                    what,
                    row,
                    disp(r.ampacity),
                    disp(prev.ampacity)
                ));
            }
        }
    }
    let mut m = Map::new();
    m.insert("material", Value::Str(material));
    m.insert("temperature", Value::f(temperature));
    m.insert("insulation", Value::Str(insulation));
    if let Some(n) = note {
        m.insert("note", Value::Str(n));
    }
    m.insert("sizes", Value::Arr(sizes.iter().map(size_value).collect()));
    let v = Value::Obj(m);
    put(pr, "wire_types", &name, &target, v.clone());
    lib_follow(pr, "wire-type", &name, &target, existing.is_some());
    super::mark_step();
    Ok(jobj! {"name" => target, "wire_type" => v})
}

//! Reinforcement presets: `reinforcement_preset`.
//!
//! The file keeps them in `reinforcement` (left out while there are none), each by name in name
//! order: its `kind` and the `params` `reinforce` takes for it, as given (only their names are
//! checked against the kind); the library names each (`reinforcement-preset`).

use super::common::*;
use crate::json::Value;
use crate::project::Project;
use crate::session::Session;

pub const SECTION: &str = "reinforcement";
const LIB: &str = "reinforcement-preset";
pub const KINDS: &[&str] = &["beam", "column", "footing", "floor"];

/// The parameters of `reinforce` a preset of a kind may hold.
pub fn params_of(kind: &str) -> &'static [&'static str] {
    match kind {
        "beam" => &["cover", "grade", "grade_stirrup", "clearance", "bottom", "top", "stirrup", "skin", "anchor"],
        "column" => &["cover", "grade", "grade_stirrup", "clearance", "bars", "stirrup", "ties", "anchor"],
        "footing" => &["cover", "grade", "grade_stirrup", "clearance", "mesh"],
        "floor" => &["cover", "grade", "grade_stirrup", "clearance", "bottom", "top"],
        _ => &[],
    }
}

/// A preset by its name or its GUID: its kind and its params, for `reinforce {preset}`.
pub fn find(pr: &Project, name: &str) -> Option<(String, Value)> {
    let name = super::electrical::resolve(pr, LIB, name.trim());
    let e = pr.section(SECTION)?.get(&name)?;
    Some((name, e.clone()))
}

pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    let _ = cid;
    const CMD: &str = "reinforcement_preset";
    check_keys(p, CMD, &["name", "kind", "params", "rename", "delete"])?;
    let pr = &mut s.project;
    let Some(name) = opt_name(p, CMD, "name")? else {
        return Ok(jobj! {"presets" => Value::Obj(section(pr, SECTION))});
    };
    let name = super::electrical::resolve(pr, LIB, &name);
    let existing = pr.section(SECTION).and_then(|m| m.get(&name)).cloned();
    if opt_bool(p, CMD, "delete")? == Some(true) {
        if existing.is_none() {
            return Err(format!("{}: there's no reinforcement preset `{}`", CMD, name));
        }
        let sec = pr.section_mut(SECTION);
        sec.remove(&name);
        if sec.is_empty() {
            pr.remove_top(SECTION);
        }
        lib_remove(pr, LIB, &name);
        super::mark_step();
        return Ok(jobj! {"deleted" => name});
    }
    let rename = opt_name(p, CMD, "rename")?;
    let new = existing.is_none();
    let kind = crate::commands::params::opt_text(p, CMD, "kind")?;
    if kind.is_none() && new {
        return Err(format!("{}: `kind` (beam, column, footing, floor) is required for a new preset", CMD));
    }
    let params = match p.get("params") {
        None | Some(Value::Null) => None,
        Some(v @ Value::Obj(_)) => Some(v.clone().sorted()),
        Some(v) => {
            return Err(format!("{}: `params` must be an object of reinforce's parameters, got {}", CMD, v.to_compact()))
        }
    };
    if params.is_none() && new {
        return Err(format!("{}: `params` {{…}} is required for a new preset", CMD));
    }
    let target = rename.unwrap_or_else(|| name.clone());
    if target != name && pr.section(SECTION).map(|m| m.contains(&target)).unwrap_or(false) {
        return Err(format!("{}: there's already a reinforcement preset `{}`", CMD, target));
    }
    let old = existing.clone().unwrap_or_else(Value::obj);
    let kind = kind.or_else(|| old.get("kind").and_then(|k| k.as_str()).map(|k| k.to_string())).unwrap_or_default();
    let params = params.or_else(|| old.get("params").cloned()).unwrap_or_else(Value::obj);
    let what = format!("{}: reinforcement preset `{}`", CMD, target);
    if !KINDS.contains(&kind.as_str()) {
        return Err(format!("{}: `kind` is one of {}, not `{}`", what, KINDS.join(", "), kind));
    }
    let allowed = params_of(&kind);
    if let Some(m) = params.as_obj() {
        for k in m.keys() {
            if !allowed.contains(&k.as_str()) {
                return Err(format!("{}: `{}` isn't a parameter of a {}: {}", what, k, kind, allowed.join(", ")));
            }
        }
    }
    let v = jobj! {"kind" => kind, "params" => params};
    {
        let sec = pr.section_mut(SECTION);
        if target != name {
            sec.remove(&name);
        }
        sec.insert_sorted(&target, v.clone());
    }
    if existing.is_some() {
        if target != name {
            lib_rename(pr, LIB, &name, &target);
        }
    } else {
        lib_ensure(pr, LIB, &target);
    }
    super::mark_step();
    Ok(jobj! {"name" => target, "preset" => v})
}

//! Project parameters: `parameter`.
//!
//! The file keeps them in `parameters`, by name in name order: `{kind, categories}` (the categories
//! in name order), and the library names each (`parameter`) with its GUID. An element holds its
//! values in its `params`, by the parameter's GUID; so do schedules' fields, filters and sorts and
//! view filters' rules. Renamed, a parameter keeps its GUID and all of that follows; taken off a
//! category, that category's elements and schedules lose it; deleted, every one does. A view
//! filter with a rule on it keeps it from going.

use super::common::*;
use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;

const CMD: &str = "parameter";
const LIB: &str = "parameter";

/// The categories a project parameter can be for, in the order the original lists them.
pub const CATEGORIES: &[&str] = &[
    "wall",
    "floor",
    "ceiling",
    "roof",
    "door",
    "window",
    "room",
    "column",
    "component",
    "stair",
    "ramp",
    "railing",
    "mass",
    "structuralcolumn",
    "footing",
    "beam",
    "stripfooting",
    "pipe",
    "duct",
    "conduit",
    "cabletray",
    "wire",
    "downconductor",
    "groundconductor",
    "cable",
];

pub const KINDS: &[&str] = &["text", "number", "length", "yesno"];

/// Names elements hold their phase, design option, paint and mass under.
pub const RESERVED: &[&str] = &["Phase Created", "Phase Demolished", "Design Option", "Paint", "Mass Floor"];

/// The fields a category's elements have of their own (its schedule's, but the phasing ones).
pub fn own_fields(cat: &str) -> &'static [&'static str] {
    match cat {
        "wall" => &["Id", "Type", "Level", "Length", "Height", "Thickness", "Count"],
        "floor" => &["Id", "Type", "Level", "Area", "Thickness", "Offset", "Count", "Structural"],
        "ceiling" => &["Id", "Type", "Level", "Offset", "Area", "Thickness", "Count"],
        "roof" => &["Id", "Type", "Level", "Slope", "Plan Area", "Offset", "Count"],
        "door" => &["Mark", "Type", "Width", "Height", "Level", "Wall", "Family", "Operation", "Count"],
        "window" => &["Mark", "Type", "Width", "Height", "Sill", "Level", "Wall", "Family", "Operation", "Count"],
        "room" => &["Number", "Name", "Level", "Area", "Perimeter", "Count", "Unbounded Height", "Volume"],
        "column" | "structuralcolumn" => &["Id", "Type", "Level", "Width", "Depth", "Height", "Count"],
        "component" => &["Family", "Type", "Level", "Count"],
        "stair" => &["Id", "Level", "Width", "Height", "Risers", "Riser Height", "Tread", "Length", "Count"],
        "ramp" => &["Id", "Level", "Width", "Height", "Length", "Slope", "Count"],
        "railing" => &["Id", "Type", "Level", "Length", "Height", "Count"],
        "mass" => &["Name", "Level", "Height", "Area", "Volume", "Gross Floor Area", "Count"],
        "footing" => &["Id", "Type", "Level", "Width", "Depth", "Thickness", "Count"],
        "beam" | "stripfooting" => &["Id", "Type", "Level", "Length", "Width", "Depth", "System", "Count"],
        "pipe" | "conduit" | "wire" | "cable" => &["Id", "Type", "Level", "System", "Length", "Diameter", "Count"],
        "duct" | "cabletray" | "downconductor" | "groundconductor" => {
            &["Id", "Type", "Level", "System", "Length", "Width", "Depth", "Count"]
        }
        _ => &[],
    }
}

/// A category as typed (any case, spaces, `_` or `-`, plural): its key.
pub fn category_of(s: &str) -> Option<&'static str> {
    let key: String = s.chars().filter(|c| c.is_ascii_alphanumeric()).collect::<String>().to_ascii_lowercase();
    if let Some(c) = CATEGORIES.iter().find(|c| **c == key) {
        return Some(c);
    }
    let bare = key.trim_end_matches('s');
    for c in CATEGORIES {
        if c.ends_with('s') {
            if key == format!("{}es", c) {
                return Some(c);
            }
        } else if *c == bare {
            return Some(c);
        }
    }
    None
}

/// A name as a parameter may have it: a letter (or `_`) first, then letters, digits, `_` and spaces.
fn name_ok(n: &str) -> bool {
    let mut cs = n.chars();
    match cs.next() {
        Some(c) if c.is_alphabetic() || c == '_' => {}
        _ => return false,
    }
    cs.all(|c| c.is_alphanumeric() || c == '_' || c == ' ')
}

/// A parameter by its name or its GUID: its name.
pub fn resolve(pr: &Project, name: &str) -> String {
    super::electrical::resolve(pr, LIB, name)
}

/// The project parameter an element's `params` key names (its GUID, or its name): its name.
pub fn param_of_key(pr: &Project, key: &str) -> Option<String> {
    if let Some(g) = crate::model::normalize_guid(key) {
        if let Some(e) = pr.library.values().find(|e| e.get("guid").and_then(|x| x.as_str()) == Some(g.as_str())) {
            if e.get("kind").and_then(|k| k.as_str()) == Some(LIB) {
                return e.get("name").and_then(|n| n.as_str()).map(|n| n.to_string());
            }
            return None;
        }
    }
    if pr.section("parameters").map(|m| m.contains(key)).unwrap_or(false) {
        return Some(key.to_string());
    }
    None
}

/// Whether a key of an element's `params` is this parameter's (its GUID, or its name).
fn is_key(k: &str, guid: &Option<String>, name: &str) -> bool {
    k == name || guid.as_deref() == Some(k)
}

fn cats_of(v: &Value) -> Vec<String> {
    v.get("categories")
        .and_then(|c| c.as_arr())
        .map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect())
        .unwrap_or_default()
}

/// Whether any element holds a value of it.
fn has_values(pr: &Project, guid: &Option<String>, name: &str) -> bool {
    pr.elements.values().any(|e| {
        e.get("params")
            .and_then(|p| p.as_obj())
            .map(|m| m.keys().any(|k| is_key(k, guid, name)))
            .unwrap_or(false)
    })
}

/// The first view filter (by name) with a rule on it, among those of these categories (any, for None).
fn filter_with_rule(pr: &Project, guid: &Option<String>, name: &str, cats: Option<&[String]>) -> Option<String> {
    let filters = section(pr, "view_filters");
    let mut names: Vec<&String> = filters.keys().collect();
    names.sort();
    for fname in names {
        let f = filters.get(fname).unwrap();
        if let Some(cats) = cats {
            let fc = cats_of(f);
            if !fc.iter().any(|c| cats.contains(c)) {
                continue;
            }
        }
        let rules = f.get("rules").and_then(|r| r.as_arr()).cloned().unwrap_or_default();
        if rules.iter().any(|r| r.get("field").and_then(|x| x.as_str()).map(|x| is_key(x, guid, name)).unwrap_or(false)) {
            return Some(fname.clone());
        }
    }
    None
}

/// Takes the parameter's values off the elements (of these categories; all, for None), and its
/// fields, filters and sorts off the schedules of them.
fn strip(pr: &mut Project, guid: &Option<String>, name: &str, cats: Option<&[String]>) {
    for e in pr.elements.values_mut() {
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        if cat == "schedule" {
            let of = e.get("of").and_then(|c| c.as_str()).unwrap_or("").to_string();
            if cats.map(|cs| cs.contains(&of)).unwrap_or(true) {
                strip_schedule(e, guid, name);
            }
            continue;
        }
        if !cats.map(|cs| cs.contains(&cat)).unwrap_or(true) {
            continue;
        }
        let mut empty = false;
        if let Some(Value::Obj(m)) = e.get_mut("params") {
            m.items.retain(|(k, _)| !is_key(k, guid, name));
            empty = m.is_empty();
        }
        if empty {
            e.remove("params");
        }
    }
}

fn strip_schedule(e: &mut Value, guid: &Option<String>, name: &str) {
    for (list, key) in [("fields", "name"), ("filters", "field"), ("sort", "field")] {
        let mut empty = false;
        if let Some(Value::Arr(a)) = e.get_mut(list) {
            let before = a.len();
            a.retain(|x| !x.get(key).and_then(|f| f.as_str()).map(|f| is_key(f, guid, name)).unwrap_or(false));
            empty = a.is_empty() && before > 0;
        }
        if empty {
            e.remove(list);
        }
    }
}

fn shown(v: &Value) -> Value {
    v.clone().sorted()
}

pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    let _ = cid;
    let pr = &mut s.project;
    let Some(name) = opt_name(p, CMD, "name")? else {
        return Err(format!("{}: `name` is required", CMD));
    };
    let name = resolve(pr, &name);
    let existing = pr.section("parameters").and_then(|m| m.get(&name)).cloned();
    let guid = pr.lib_guid(LIB, &name);
    if opt_bool(p, CMD, "delete")? == Some(true) {
        if existing.is_none() {
            return Err(format!("{}: there's no parameter `{}`", CMD, name));
        }
        if let Some(f) = filter_with_rule(pr, &guid, &name, None) {
            return Err(format!(
                "{}: view filter `{}` has a rule on `{}`; take the rule off before the parameter goes",
                CMD, f, name
            ));
        }
        strip(pr, &guid, &name, None);
        pr.section_mut("parameters").remove(&name);
        lib_remove(pr, LIB, &name);
        super::mark_step();
        return Ok(jobj! {"deleted" => name});
    }
    let kind = match p.get("kind") {
        None | Some(Value::Null) => None,
        Some(Value::Str(k)) if KINDS.contains(&k.as_str()) => Some(k.clone()),
        Some(v) => {
            return Err(format!("{}: `kind`: {} isn't one of {}", CMD, v.to_compact(), KINDS.join(", ")));
        }
    };
    let old_kind = existing.as_ref().and_then(|e| e.get("kind")).and_then(|k| k.as_str()).map(|k| k.to_string());
    if let (Some(k), Some(ok)) = (&kind, &old_kind) {
        if k != ok && has_values(pr, &guid, &name) {
            return Err(format!(
                "{}: `{}` has values of its kind; take them away before it holds another",
                CMD, name
            ));
        }
    }
    let cats: Option<Vec<String>> = match p.get("categories") {
        None | Some(Value::Null) => None,
        Some(Value::Arr(a)) if a.iter().all(|x| matches!(x, Value::Str(_))) => {
            let mut out: Vec<String> = Vec::new();
            for x in a {
                let t = x.as_str().unwrap();
                let c = category_of(t).ok_or_else(|| {
                    format!("{}: `{}` isn't a category it can be for; there are {}", CMD, t, CATEGORIES.join(", "))
                })?;
                if !out.iter().any(|o| o == c) {
                    out.push(c.to_string());
                }
            }
            out.sort();
            Some(out)
        }
        Some(v) => return Err(format!("{}: `categories` is a list of categories, not {}", CMD, v.to_compact())),
    };
    let old_cats = existing.as_ref().map(cats_of).unwrap_or_default();
    let removed: Vec<String> = match (&cats, &existing) {
        (Some(c), Some(_)) => old_cats.iter().filter(|o| !c.contains(o)).cloned().collect(),
        _ => Vec::new(),
    };
    if !removed.is_empty() {
        if let Some(f) = filter_with_rule(pr, &guid, &name, Some(&removed)) {
            return Err(format!(
                "{}: view filter `{}` has a rule on `{}`; take the rule off before the parameter goes",
                CMD, f, name
            ));
        }
    }
    let rename = match crate::commands::params::opt_text(p, CMD, "rename")? {
        None => None,
        Some(r) => {
            let t = r.trim();
            if t.is_empty() {
                return Err(format!("{}: `rename` needs a name", CMD));
            }
            Some(t.to_string())
        }
    };
    let target = rename.unwrap_or_else(|| name.clone());
    if target != name && pr.section("parameters").map(|m| m.contains(&target)).unwrap_or(false) {
        return Err(format!("{}: there's a parameter `{}` already", CMD, target));
    }
    let what = format!("{} `{}`", CMD, target);
    if !name_ok(&target) {
        return Err(format!(
            "{}: a name starts with a letter and holds letters, digits, `_` and spaces, up to 256",
            what
        ));
    }
    if RESERVED.contains(&target.as_str()) {
        return Err(format!(
            "{}: elements hold their phase, their design option, their paint and their mass under that name; name it otherwise",
            what
        ));
    }
    let cats = cats.unwrap_or_else(|| old_cats.clone());
    if cats.is_empty() {
        return Err(format!("{}: it needs a category: one of {}", what, CATEGORIES.join(", ")));
    }
    for c in &cats {
        if own_fields(c).contains(&target.as_str()) {
            return Err(format!("{}: {}s have a `{}` of their own; name it otherwise", what, c, target));
        }
    }
    if cats.iter().any(|c| c == "component") {
        let fams = section(pr, "families");
        let mut fnames: Vec<&String> = fams.keys().collect();
        fnames.sort();
        for fname in fnames {
            let f = fams.get(fname).unwrap();
            let has = f
                .get("parameters")
                .and_then(|x| x.as_arr())
                .map(|a| a.iter().any(|x| x.get("name").and_then(|n| n.as_str()) == Some(target.as_str())))
                .unwrap_or(false);
            if has {
                return Err(format!(
                    "{}: family `{}` has a parameter of that name; name it otherwise",
                    what, fname
                ));
            }
        }
    }
    let kind = kind.or(old_kind).unwrap_or_else(|| "text".to_string());
    if !removed.is_empty() {
        strip(pr, &guid, &name, Some(&removed));
    }
    if target != name {
        // values kept by name follow it (GUID keys need nothing)
        for e in pr.elements.values_mut() {
            if let Some(Value::Obj(m)) = e.get_mut("params") {
                for (k, _) in m.items.iter_mut() {
                    if *k == name && guid.as_deref() != Some(k.as_str()) {
                        *k = target.clone();
                    }
                }
            }
        }
    }
    let mut m = Map::new();
    m.insert("kind", Value::Str(kind));
    m.insert("categories", Value::Arr(cats.iter().map(|c| Value::Str(c.clone())).collect()));
    let v = Value::Obj(m);
    {
        let sec = pr.section_mut("parameters");
        if target != name {
            sec.remove(&name);
        }
        sec.insert_sorted(&target, v.clone());
    }
    if existing.is_some() {
        if target != name {
            lib_rename(pr, LIB, &name, &target);
        }
    } else {
        lib_ensure(pr, LIB, &target);
    }
    super::mark_step();
    Ok(jobj! {"name" => target, "parameter" => shown(&v)})
}

/// What `inspect` says of the project's parameters.
pub fn inspect_entries(s: &Session, out: &mut Vec<(String, Value)>) {
    out.push(("parameters".into(), Value::Obj(section(&s.project, "parameters")).sorted()));
}

/// The largest number or length a value may be, either way.
const MAX_VALUE: f64 = 1e9;

/// Whether a value is one a parameter of this kind holds; else what it holds, for the error.
pub fn value_fits(kind: &str, v: &Value) -> Result<(), &'static str> {
    match kind {
        "text" => match v {
            Value::Str(s) if s.chars().count() <= 256 => Ok(()),
            _ => Err("text"),
        },
        "number" | "length" => match v {
            Value::Num(n) if n.as_f64().is_finite() && n.as_f64().abs() <= MAX_VALUE => Ok(()),
            _ => Err(if kind == "number" { "a number" } else { "a length" }),
        },
        "yesno" => match v {
            Value::Bool(_) => Ok(()),
            _ => Err("yes or no"),
        },
        _ => Ok(()),
    }
}

/// The names of the parameters of an element's own family (a component's, a door's…), whose
/// instance values it may hold in `params` too.
fn family_params(pr: &Project, e: &Value) -> Vec<String> {
    let Some(f) = e.get("family").and_then(|f| f.as_str()) else {
        return Vec::new();
    };
    let fname = name_of_guid(pr, "family", f).unwrap_or_else(|| f.to_string());
    pr.section("families")
        .and_then(|m| m.get(&fname))
        .and_then(|fam| fam.get("parameters"))
        .and_then(|a| a.as_arr())
        .map(|a| a.iter().filter_map(|x| x.get("name").and_then(|n| n.as_str()).map(|n| n.to_string())).collect())
        .unwrap_or_default()
}

/// The model rules of project parameters: each value an element holds is of a parameter of its
/// category, and of its kind.
pub fn check(pr: &Project) -> R<()> {
    let params = section(pr, "parameters");
    for (id, e) in &pr.elements {
        let Some(m) = e.get("params").and_then(|p| p.as_obj()) else {
            continue;
        };
        if m.is_empty() {
            continue;
        }
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        let mut keys: Vec<&(String, Value)> = m.items.iter().collect();
        keys.sort_by(|a, b| a.0.cmp(&b.0));
        let mut fam: Option<Vec<String>> = None;
        for (k, v) in keys {
            if RESERVED.contains(&k.as_str()) || v.is_null() {
                continue;
            }
            // a family parameter's value (by its GUID), checked by its family
            if let Some(g) = crate::model::normalize_guid(k) {
                if let Some(le) = pr.library.values().find(|x| x.get("guid").and_then(|g2| g2.as_str()) == Some(g.as_str())) {
                    if le.get("kind").and_then(|x| x.as_str()) != Some(LIB) {
                        continue;
                    }
                }
            }
            let pname = param_of_key(pr, k);
            let def = pname.as_ref().and_then(|n| params.get(n));
            let shown_name = pname.clone().unwrap_or_else(|| k.clone());
            let Some(def) = def.filter(|d| cats_of(d).iter().any(|c| c == cat)) else {
                if pname.is_none() {
                    let fp = fam.get_or_insert_with(|| family_params(pr, e));
                    if fp.contains(k) {
                        continue;
                    }
                }
                return Err(format!(
                    "{} {}: `{}` isn't a parameter of {}s; add it with `parameter`",
                    cat, id, shown_name, cat
                ));
            };
            let kind = def.get("kind").and_then(|k| k.as_str()).unwrap_or("text");
            if let Err(holds) = value_fits(kind, v) {
                return Err(format!("{} {}: `{}` holds {}, not {}", cat, id, shown_name, holds, v.to_compact()));
            }
        }
    }
    Ok(())
}

//! Project parameters: `parameter`.
//!
//! The file keeps them in `parameters`, by name in name order: `{kind, categories}` (the categories
//! in name order), and the library names each (`parameter`) with its GUID. An element holds its
//! values in its `params`, by the parameter's GUID; so do schedules' fields, filters and sorts and
//! view filters' rules. Renamed, a parameter keeps its GUID and all of that follows; taken off a
//! category, that category's elements and schedules lose it; deleted, every one does. A view
//! filter with a rule on it keeps it from going.

use super::common::*;
use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;

const CMD: &str = "parameter";
const LIB: &str = "parameter";

/// The categories a project parameter can be for, in the order the original lists them.
pub const CATEGORIES: &[&str] = &[
    "wall",
    "floor",
    "ceiling",
    "roof",
    "door",
    "window",
    "room",
    "column",
    "component",
    "stair",
    "ramp",
    "railing",
    "mass",
    "structuralcolumn",
    "footing",
    "beam",
    "stripfooting",
    "pipe",
    "duct",
    "conduit",
    "cabletray",
    "wire",
    "downconductor",
    "groundconductor",
    "cable",
];

pub const KINDS: &[&str] = &["text", "number", "length", "yesno"];

/// Names elements hold their phase, design option, paint and mass under.
pub const RESERVED: &[&str] = &["Phase Created", "Phase Demolished", "Design Option", "Paint", "Mass Floor"];

/// The fields a category's elements have of their own (its schedule's, but the phasing ones).
pub fn own_fields(cat: &str) -> &'static [&'static str] {
    match cat {
        "wall" => &["Id", "Type", "Level", "Length", "Height", "Thickness", "Count"],
        "floor" => &["Id", "Type", "Level", "Area", "Thickness", "Offset", "Count", "Structural"],
        "ceiling" => &["Id", "Type", "Level", "Offset", "Area", "Thickness", "Count"],
        "roof" => &["Id", "Type", "Level", "Slope", "Plan Area", "Offset", "Count"],
        "door" => &["Mark", "Type", "Width", "Height", "Level", "Wall", "Family", "Operation", "Count"],
        "window" => &["Mark", "Type", "Width", "Height", "Sill", "Level", "Wall", "Family", "Operation", "Count"],
        "room" => &["Number", "Name", "Level", "Area", "Perimeter", "Count", "Unbounded Height", "Volume"],
        "column" | "structuralcolumn" => &["Id", "Type", "Level", "Width", "Depth", "Height", "Count"],
        "component" => &["Family", "Type", "Level", "Count"],
        "stair" => &["Id", "Level", "Width", "Height", "Risers", "Riser Height", "Tread", "Length", "Count"],
        "ramp" => &["Id", "Level", "Width", "Height", "Length", "Slope", "Count"],
        "railing" => &["Id", "Type", "Level", "Length", "Height", "Count"],
        "mass" => &["Name", "Level", "Height", "Area", "Volume", "Gross Floor Area", "Count"],
        "footing" => &["Id", "Type", "Level", "Width", "Depth", "Thickness", "Count"],
        "beam" | "stripfooting" => &["Id", "Type", "Level", "Length", "Width", "Depth", "System", "Count"],
        "pipe" | "conduit" | "wire" | "cable" => &["Id", "Type", "Level", "System", "Length", "Diameter", "Count"],
        "duct" | "cabletray" | "downconductor" | "groundconductor" => {
            &["Id", "Type", "Level", "System", "Length", "Width", "Depth", "Count"]
        }
        _ => &[],
    }
}

/// A category as typed (any case, spaces, `_` or `-`, plural): its key.
pub fn category_of(s: &str) -> Option<&'static str> {
    let key: String = s.chars().filter(|c| c.is_ascii_alphanumeric()).collect::<String>().to_ascii_lowercase();
    if let Some(c) = CATEGORIES.iter().find(|c| **c == key) {
        return Some(c);
    }
    let bare = key.trim_end_matches('s');
    for c in CATEGORIES {
        if c.ends_with('s') {
            if key == format!("{}es", c) {
                return Some(c);
            }
        } else if *c == bare {
            return Some(c);
        }
    }
    None
}

/// A name as a parameter may have it: a letter (or `_`) first, then letters, digits, `_` and spaces.
fn name_ok(n: &str) -> bool {
    let mut cs = n.chars();
    match cs.next() {
        Some(c) if c.is_alphabetic() || c == '_' => {}
        _ => return false,
    }
    cs.all(|c| c.is_alphanumeric() || c == '_' || c == ' ')
}

/// A parameter by its name or its GUID: its name.
pub fn resolve(pr: &Project, name: &str) -> String {
    super::electrical::resolve(pr, LIB, name)
}

/// The project parameter an element's `params` key names (its GUID, or its name): its name.
pub fn param_of_key(pr: &Project, key: &str) -> Option<String> {
    if let Some(g) = crate::model::normalize_guid(key) {
        if let Some(e) = pr.library.values().find(|e| e.get("guid").and_then(|x| x.as_str()) == Some(g.as_str())) {
            if e.get("kind").and_then(|k| k.as_str()) == Some(LIB) {
                return e.get("name").and_then(|n| n.as_str()).map(|n| n.to_string());
            }
            return None;
        }
    }
    if pr.section("parameters").map(|m| m.contains(key)).unwrap_or(false) {
        return Some(key.to_string());
    }
    None
}

/// Whether a key of an element's `params` is this parameter's (its GUID, or its name).
fn is_key(k: &str, guid: &Option<String>, name: &str) -> bool {
    k == name || guid.as_deref() == Some(k)
}

fn cats_of(v: &Value) -> Vec<String> {
    v.get("categories")
        .and_then(|c| c.as_arr())
        .map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect())
        .unwrap_or_default()
}

/// Whether any element holds a value of it.
fn has_values(pr: &Project, guid: &Option<String>, name: &str) -> bool {
    pr.elements.values().any(|e| {
        e.get("params")
            .and_then(|p| p.as_obj())
            .map(|m| m.keys().any(|k| is_key(k, guid, name)))
            .unwrap_or(false)
    })
}

/// The first view filter (by name) with a rule on it, among those of these categories (any, for None).
fn filter_with_rule(pr: &Project, guid: &Option<String>, name: &str, cats: Option<&[String]>) -> Option<String> {
    let filters = section(pr, "view_filters");
    let mut names: Vec<&String> = filters.keys().collect();
    names.sort();
    for fname in names {
        let f = filters.get(fname).unwrap();
        if let Some(cats) = cats {
            let fc = cats_of(f);
            if !fc.iter().any(|c| cats.contains(c)) {
                continue;
            }
        }
        let rules = f.get("rules").and_then(|r| r.as_arr()).cloned().unwrap_or_default();
        if rules.iter().any(|r| r.get("field").and_then(|x| x.as_str()).map(|x| is_key(x, guid, name)).unwrap_or(false)) {
            return Some(fname.clone());
        }
    }
    None
}

/// Takes the parameter's values off the elements (of these categories; all, for None), and its
/// fields, filters and sorts off the schedules of them.
fn strip(pr: &mut Project, guid: &Option<String>, name: &str, cats: Option<&[String]>) {
    for e in pr.elements.values_mut() {
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        if cat == "schedule" {
            let of = e.get("of").and_then(|c| c.as_str()).unwrap_or("").to_string();
            if cats.map(|cs| cs.contains(&of)).unwrap_or(true) {
                strip_schedule(e, guid, name);
            }
            continue;
        }
        if !cats.map(|cs| cs.contains(&cat)).unwrap_or(true) {
            continue;
        }
        let mut empty = false;
        if let Some(Value::Obj(m)) = e.get_mut("params") {
            m.items.retain(|(k, _)| !is_key(k, guid, name));
            empty = m.is_empty();
        }
        if empty {
            e.remove("params");
        }
    }
}

fn strip_schedule(e: &mut Value, guid: &Option<String>, name: &str) {
    for (list, key) in [("fields", "name"), ("filters", "field"), ("sort", "field")] {
        let mut empty = false;
        if let Some(Value::Arr(a)) = e.get_mut(list) {
            let before = a.len();
            a.retain(|x| !x.get(key).and_then(|f| f.as_str()).map(|f| is_key(f, guid, name)).unwrap_or(false));
            empty = a.is_empty() && before > 0;
        }
        if empty {
            e.remove(list);
        }
    }
}

fn shown(v: &Value) -> Value {
    v.clone().sorted()
}

pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    let _ = cid;
    let pr = &mut s.project;
    let Some(name) = opt_name(p, CMD, "name")? else {
        return Err(format!("{}: `name` is required", CMD));
    };
    let name = resolve(pr, &name);
    let existing = pr.section("parameters").and_then(|m| m.get(&name)).cloned();
    let guid = pr.lib_guid(LIB, &name);
    if opt_bool(p, CMD, "delete")? == Some(true) {
        if existing.is_none() {
            return Err(format!("{}: there's no parameter `{}`", CMD, name));
        }
        if let Some(f) = filter_with_rule(pr, &guid, &name, None) {
            return Err(format!(
                "{}: view filter `{}` has a rule on `{}`; take the rule off before the parameter goes",
                CMD, f, name
            ));
        }
        strip(pr, &guid, &name, None);
        pr.section_mut("parameters").remove(&name);
        lib_remove(pr, LIB, &name);
        super::mark_step();
        return Ok(jobj! {"deleted" => name});
    }
    let kind = match p.get("kind") {
        None | Some(Value::Null) => None,
        Some(Value::Str(k)) if KINDS.contains(&k.as_str()) => Some(k.clone()),
        Some(v) => {
            return Err(format!("{}: `kind`: {} isn't one of {}", CMD, v.to_compact(), KINDS.join(", ")));
        }
    };
    let old_kind = existing.as_ref().and_then(|e| e.get("kind")).and_then(|k| k.as_str()).map(|k| k.to_string());
    if let (Some(k), Some(ok)) = (&kind, &old_kind) {
        if k != ok && has_values(pr, &guid, &name) {
            return Err(format!(
                "{}: `{}` has values of its kind; take them away before it holds another",
                CMD, name
            ));
        }
    }
    let cats: Option<Vec<String>> = match p.get("categories") {
        None | Some(Value::Null) => None,
        Some(Value::Arr(a)) if a.iter().all(|x| matches!(x, Value::Str(_))) => {
            let mut out: Vec<String> = Vec::new();
            for x in a {
                let t = x.as_str().unwrap();
                let c = category_of(t).ok_or_else(|| {
                    format!("{}: `{}` isn't a category it can be for; there are {}", CMD, t, CATEGORIES.join(", "))
                })?;
                if !out.iter().any(|o| o == c) {
                    out.push(c.to_string());
                }
            }
            out.sort();
            Some(out)
        }
        Some(v) => return Err(format!("{}: `categories` is a list of categories, not {}", CMD, v.to_compact())),
    };
    let old_cats = existing.as_ref().map(cats_of).unwrap_or_default();
    let removed: Vec<String> = match (&cats, &existing) {
        (Some(c), Some(_)) => old_cats.iter().filter(|o| !c.contains(o)).cloned().collect(),
        _ => Vec::new(),
    };
    if !removed.is_empty() {
        if let Some(f) = filter_with_rule(pr, &guid, &name, Some(&removed)) {
            return Err(format!(
                "{}: view filter `{}` has a rule on `{}`; take the rule off before the parameter goes",
                CMD, f, name
            ));
        }
    }
    let rename = match crate::commands::params::opt_text(p, CMD, "rename")? {
        None => None,
        Some(r) => {
            let t = r.trim();
            if t.is_empty() {
                return Err(format!("{}: `rename` needs a name", CMD));
            }
            Some(t.to_string())
        }
    };
    let target = rename.unwrap_or_else(|| name.clone());
    if target != name && pr.section("parameters").map(|m| m.contains(&target)).unwrap_or(false) {
        return Err(format!("{}: there's a parameter `{}` already", CMD, target));
    }
    let what = format!("{} `{}`", CMD, target);
    if !name_ok(&target) {
        return Err(format!(
            "{}: a name starts with a letter and holds letters, digits, `_` and spaces, up to 256",
            what
        ));
    }
    if RESERVED.contains(&target.as_str()) {
        return Err(format!(
            "{}: elements hold their phase, their design option, their paint and their mass under that name; name it otherwise",
            what
        ));
    }
    let cats = cats.unwrap_or_else(|| old_cats.clone());
    if cats.is_empty() {
        return Err(format!("{}: it needs a category: one of {}", what, CATEGORIES.join(", ")));
    }
    for c in &cats {
        if own_fields(c).contains(&target.as_str()) {
            return Err(format!("{}: {}s have a `{}` of their own; name it otherwise", what, c, target));
        }
    }
    if cats.iter().any(|c| c == "component") {
        let fams = section(pr, "families");
        let mut fnames: Vec<&String> = fams.keys().collect();
        fnames.sort();
        for fname in fnames {
            let f = fams.get(fname).unwrap();
            let has = f
                .get("parameters")
                .and_then(|x| x.as_arr())
                .map(|a| a.iter().any(|x| x.get("name").and_then(|n| n.as_str()) == Some(target.as_str())))
                .unwrap_or(false);
            if has {
                return Err(format!(
                    "{}: family `{}` has a parameter of that name; name it otherwise",
                    what, fname
                ));
            }
        }
    }
    let kind = kind.or(old_kind).unwrap_or_else(|| "text".to_string());
    if !removed.is_empty() {
        strip(pr, &guid, &name, Some(&removed));
    }
    if target != name {
        // values kept by name follow it (GUID keys need nothing)
        for e in pr.elements.values_mut() {
            if let Some(Value::Obj(m)) = e.get_mut("params") {
                for (k, _) in m.items.iter_mut() {
                    if *k == name && guid.as_deref() != Some(k.as_str()) {
                        *k = target.clone();
                    }
                }
            }
        }
    }
    let mut m = Map::new();
    m.insert("kind", Value::Str(kind));
    m.insert("categories", Value::Arr(cats.iter().map(|c| Value::Str(c.clone())).collect()));
    let v = Value::Obj(m);
    {
        let sec = pr.section_mut("parameters");
        if target != name {
            sec.remove(&name);
        }
        sec.insert_sorted(&target, v.clone());
    }
    if existing.is_some() {
        if target != name {
            lib_rename(pr, LIB, &name, &target);
        }
    } else {
        lib_ensure(pr, LIB, &target);
    }
    super::mark_step();
    Ok(jobj! {"name" => target, "parameter" => shown(&v)})
}

/// What `inspect` says of the project's parameters.
pub fn inspect_entries(s: &Session, out: &mut Vec<(String, Value)>) {
    out.push(("parameters".into(), Value::Obj(section(&s.project, "parameters")).sorted()));
}

/// The largest number or length a value may be, either way.
const MAX_VALUE: f64 = 1e9;

/// Whether a value is one a parameter of this kind holds; else what it holds, for the error.
pub fn value_fits(kind: &str, v: &Value) -> Result<(), &'static str> {
    match kind {
        "text" => match v {
            Value::Str(s) if s.chars().count() <= 256 => Ok(()),
            _ => Err("text"),
        },
        "number" | "length" => match v {
            Value::Num(n) if n.as_f64().is_finite() && n.as_f64().abs() <= MAX_VALUE => Ok(()),
            _ => Err(if kind == "number" { "a number" } else { "a length" }),
        },
        "yesno" => match v {
            Value::Bool(_) => Ok(()),
            _ => Err("yes or no"),
        },
        _ => Ok(()),
    }
}

/// The names of the parameters of an element's own family (a component's, a door's…), whose
/// instance values it may hold in `params` too.
fn family_params(pr: &Project, e: &Value) -> Vec<String> {
    let Some(f) = e.get("family").and_then(|f| f.as_str()) else {
        return Vec::new();
    };
    let fname = name_of_guid(pr, "family", f).unwrap_or_else(|| f.to_string());
    pr.section("families")
        .and_then(|m| m.get(&fname))
        .and_then(|fam| fam.get("parameters"))
        .and_then(|a| a.as_arr())
        .map(|a| a.iter().filter_map(|x| x.get("name").and_then(|n| n.as_str()).map(|n| n.to_string())).collect())
        .unwrap_or_default()
}

/// The model rules of project parameters: each value an element holds is of a parameter of its
/// category, and of its kind.
pub fn check(pr: &Project) -> R<()> {
    let params = section(pr, "parameters");
    for (id, e) in &pr.elements {
        let Some(m) = e.get("params").and_then(|p| p.as_obj()) else {
            continue;
        };
        if m.is_empty() {
            continue;
        }
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        let mut keys: Vec<&(String, Value)> = m.items.iter().collect();
        keys.sort_by(|a, b| a.0.cmp(&b.0));
        let mut fam: Option<Vec<String>> = None;
        for (k, v) in keys {
            if RESERVED.contains(&k.as_str()) || v.is_null() {
                continue;
            }
            // a family parameter's value (by its GUID), checked by its family
            if let Some(g) = crate::model::normalize_guid(k) {
                if let Some(le) = pr.library.values().find(|x| x.get("guid").and_then(|g2| g2.as_str()) == Some(g.as_str())) {
                    if le.get("kind").and_then(|x| x.as_str()) != Some(LIB) {
                        continue;
                    }
                }
            }
            let pname = param_of_key(pr, k);
            let def = pname.as_ref().and_then(|n| params.get(n));
            let shown_name = pname.clone().unwrap_or_else(|| k.clone());
            let Some(def) = def.filter(|d| cats_of(d).iter().any(|c| c == cat)) else {
                if pname.is_none() {
                    let fp = fam.get_or_insert_with(|| family_params(pr, e));
                    if fp.contains(k) {
                        continue;
                    }
                }
                return Err(format!(
                    "{} {}: `{}` isn't a parameter of {}s; add it with `parameter`",
                    cat, id, shown_name, cat
                ));
            };
            let kind = def.get("kind").and_then(|k| k.as_str()).unwrap_or("text");
            if let Err(holds) = value_fits(kind, v) {
                return Err(format!("{} {}: `{}` holds {}, not {}", cat, id, shown_name, holds, v.to_compact()));
            }
        }
    }
    Ok(())
}

